cd /app && sqlite3 /tmp/big.sqlite3 "
UPDATE users SET account_id = X'000000000000000000000081C2ACC6E9' WHERE hex(account_id)='0000000000000000000000720A25A251';
UPDATE users SET account_id = X'0000000000000000000000134A312654' WHERE hex(account_id)='0000000000000000000000991B69DEA9';
