cd /app && cp /tmp/big_base.sqlite3 /tmp/real.sqlite3 && sqlite3 /tmp/real.sqlite3 "
UPDATE users SET account_id = X'000000000000000000000081C2ACC6E9' WHERE hex(account_id)='0000000000000000000000720A25A251';
UPDATE users SET account_id = X'0000000000000000000000134A312654' WHERE hex(account_id)='0000000000000000000000991B69DEA9';
DELETE FROM cards WHERE number > 100000;
WITH RECURSIVE seq(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM seq WHERE n < 600)
INSERT INTO boards (id, account_id, all_access, created_at, creator_id, name, updated_at)
SELECT randomblob(16), X'000000000000000000000081C2ACC6E9', 1, datetime('now'), (SELECT id FROM users WHERE hex(account_id)='000000000000000000000081C2ACC6E9' AND role='owner'), 'b' || n, datetime('now') FROM seq;
INSERT INTO entropies (id, account_id, auto_postpone_period, container_id, container_type, created_at, updated_at)
SELECT randomblob(16), account_id, (abs(random()) % 3 + 1) * 2592000, id, 'Board', datetime('now'), datetime('now') FROM boards WHERE name LIKE 'b%' AND abs(random()) % 4 <> 0;
WITH RECURSIVE seq(n) AS (SELECT 1 UNION ALL SELECT n+1 FROM seq WHERE n < 150000),
b AS (SELECT id, account_id, row_number() OVER () - 1 AS i, count(*) OVER () AS cnt FROM boards WHERE name LIKE 'b%')
INSERT INTO cards (id, account_id, board_id, created_at, creator_id, last_active_at, number, status, title, updated_at)
SELECT randomblob(16), b.account_id, b.id, ts, (SELECT id FROM users WHERE hex(account_id)='000000000000000000000081C2ACC6E9' AND role='owner'), ts, 100000 + n, 'published', 'x', ts
FROM (SELECT n, strftime('%Y-%m-%d %H:%M:%f', 'now', '-' || (abs(random()) % 700) || ' days') || '000' AS ts FROM seq) s JOIN b ON b.i = s.n % b.cnt;
INSERT INTO closures (id, account_id, card_id, created_at, updated_at) SELECT randomblob(16), account_id, id, last_active_at, last_active_at FROM cards WHERE number > 100000 AND abs(random()) % 10 < 5;
INSERT INTO card_not_nows (id, account_id, card_id, created_at, updated_at) SELECT randomblob(16), account_id, id, last_active_at, last_active_at FROM cards c WHERE number > 100000 AND abs(random()) % 10 < 3 AND NOT EXISTS (SELECT 1 FROM closures WHERE card_id = c.id);
ANALYZE;
SELECT (SELECT count(*) FROM cards), (SELECT count(*) FROM closures), (SELECT count(*) FROM card_not_nows), (SELECT count(*) FROM boards), (SELECT count(*) FROM entropies);" && DB=/tmp/real.sqlite3 RAILS_ENV=test timeout 1200 bin/rails runner /tmp/bench.rb 2>&1 | tail -14

